def _resolve_safe_target(root: Path, rel_path: str) -> Path | None:
    """Return absolute path inside root, or None if rel_path escapes/absolute."""
    if not rel_path:
        return None
    raw = Path(rel_path)
    if raw.is_absolute():
        return None
    try:
        target = (root / rel_path).resolve()
    except Exception:
        return None
    if not _is_inside(target, root):
        return None
    return target


